$events=$pdo->query("SELECT * FROM campeonatos ORDER BY data_inicio DESC LIMIT 4")->fetchAll();
$leaders=$pdo->query("SELECT p.id,p.nome,p.disciplina,p.foto,p.pais, MAX(r.total_final) melhor FROM patinadores p LEFT JOIN resultados r ON r.patinador_id=p.id AND r.confirmado=1 GROUP BY p.id ORDER BY melhor DESC LIMIT 5")->fetchAll();
